mapper.select:
SELECT d.DEFERRED_ID as deferredId, d.DEFERRED_NO as deferredNo, d.CONTRACT_ID as contractId, c.CONTRACT_NO as contractNo, c.CONTRACT_NAME as contractName, d.DEFERRED_TYPE as deferredType, CASE d.DEFERRED_TYPE WHEN 1 THEN '预收款' WHEN 2 THEN '递延收入' ELSE '其他' END as deferredTypeName, d.DEFERRED_PERIOD as deferredPeriod, d.ORIGINAL_AMOUNT as originalAmount, d.DEFERRED_AMOUNT as deferredAmount, d.DEFERRED_AMOUNT as totalAmount, d.RECOGNIZED_AMOUNT as recognizedAmount, d.REMAINING_AMOUNT as remainingAmount, CASE WHEN d.DEFERRED_AMOUNT > 0 THEN ROUND(d.RECOGNIZED_AMOUNT / d.DEFERRED_AMOUNT * 100, 2) ELSE 0 END as recognitionProgress, d.DEFERRED_STATUS as deferredStatus, d.DEFERRED_STATUS as recognitionStatus, d.START_DATE as startDate, d.END_DATE as endDate, d.RECOGNITION_METHOD as recognitionMethod, d.BOOK_ID as bookId, d.TENANT_ID as tenantId, d.CREATE_TIME as createTime, d.UPDATE_TIME as updateTime FROM T_DEFERRED_REVENUE d LEFT JOIN T_REVENUE_CONTRACT c ON d.CONTRACT_ID = c.CONTRACT_ID AND c.IS_DELETED = 0 WHERE d.IS_DELETED = 0
AND d.DEFERRED_NO LIKE '%' || #{param.deferredNo} || '%'
AND c.CONTRACT_NO LIKE '%' || #{param.contractNo} || '%'
AND d.DEFERRED_TYPE = #{param.deferredType}
AND d.DEFERRED_STATUS = #{param.deferredStatus}
AND d.DEFERRED_STATUS = #{param.recognitionStatus}
AND d.BOOK_ID = #{param.bookId}
AND d.TENANT_ID = #{param.tenantId}
ORDER BY d.CREATE_TIME DESC

SELECT DEFERRED_ID, DEFERRED_NO, CONTRACT_ID, DEFERRED_TYPE, DEFERRED_PERIOD, ORIGINAL_AMOUNT, DEFERRED_AMOUNT, RECOGNIZED_AMOUNT, REMAINING_AMOUNT, DEFERRED_STATUS, START_DATE, END_DATE, RECOGNITION_METHOD, BOOK_ID, TENANT_ID, VERSION, IS_DELETED, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER FROM T_DEFERRED_REVENUE WHERE IS_DELETED = 0
AND DEFERRED_NO LIKE '%' || #{param.deferredNo} || '%'
AND DEFERRED_TYPE = #{param.deferredType}
AND DEFERRED_STATUS = #{param.deferredStatus}
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
ORDER BY CREATE_TIME DESC

SELECT COUNT(*) as totalDeferred, COALESCE(SUM(DEFERRED_AMOUNT), 0) as totalDeferredAmount, COALESCE(SUM(RECOGNIZED_AMOUNT), 0) as recognizedAmount, COALESCE(SUM(REMAINING_AMOUNT), 0) as remainingAmount FROM T_DEFERRED_REVENUE WHERE IS_DELETED = 0
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
